package com.worksphere.controller; import com.worksphere.dto.dispute.*; import com.worksphere.service.DisputeService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/disputes") public class DisputeController {private final DisputeService s;public DisputeController(DisputeService x){s=x;} @PostMapping public DisputeResponse create(Authentication a,@RequestBody DisputeRequest r){return s.create(a,r);} @GetMapping("/my") public Object mine(Authentication a){return s.mine(a);} }
